void (async () => {
  const { Readable, Transform, Writable } = require("node:stream");
  const { pipeline } = require("node:stream/promises");
  let output = "";
  const upper = new Transform({ transform(chunk, encoding, callback) { callback(null, chunk.toString().toUpperCase()); } });
  const sink = new Writable({ write(chunk, encoding, callback) { output += chunk.toString(); callback(); } });
  await pipeline(Readable.from(["hyper", "shell"]), upper, sink);
  console.log(output);
})();
